parameters.jsCode:
const items = (((($json.data || {}).boards || [])[0] || {}).items_page || {}).items || [];
const limit = parseInt($env.DAILY_FOLLOW_UP_LIMIT || '10', 10);
function colVal(item, colId) { const c = (item.column_values || []).find(c => c.id === colId); return c ? (c.text || '') : ''; }
const leads = items.slice(0, limit).map(it => ({
  leads_item_id: it.id,
  lead_name: colVal(it, $env.MONDAY_COL_LEAD_NAME) || it.name,
  first_name: ((colVal(it, $env.MONDAY_COL_LEAD_NAME) || it.name).split(/\s+/)[0] || 'there'),
  email: colVal(it, $env.MONDAY_COL_LEAD_EMAIL),
  subject_line: colVal(it, $env.MONDAY_COL_LEAD_SUBJECT_LINE),
  thread_id: colVal(it, $env.MONDAY_COL_LEAD_THREAD_ID)
})).filter(l => l.email && l.thread_id);
return leads.map(l => ({ json: l }));

